use super::*;use near_sdk::{testing_env,test_utils::VMContextBuilder,PromiseResult};use std::panic::{catch_unwind,AssertUnwindSafe};
const N:u128=10u128.pow(24);fn a(s:&str)->AccountId{s.parse().unwrap()}
fn ctx(who:&str,deposit:u128,time:u64,results:Vec<PromiseResult>){let usage=env::storage_usage();let mut b=VMContextBuilder::new();b.current_account_id(a("escrow.testnet")).predecessor_account_id(a(who)).signer_account_id(a(who)).attached_deposit(NearToken::from_yoctonear(deposit)).account_balance(NearToken::from_near(1000)).storage_usage(usage).block_timestamp(time).prepaid_gas(Gas::from_tgas(300));testing_env!(b.build(),near_sdk::test_vm_config(),near_sdk::RuntimeFeesConfig::test(),Default::default(),results);}
fn feature()->FeatureId{FeatureId{owner:a("merchant.testnet"),product:"app".into(),feature:"safeshare".into(),version:1}}
fn fresh()->Commitments{env::set_blockchain_interface(near_sdk::MockedBlockchain::default());ctx("merchant.testnet",0,1,vec![]);Commitments::new(a("market.testnet"))}
fn campaign(c:&mut Commitments){ctx("merchant.testnet",N,1,vec![]);c.create_campaign("build".into(),feature(),a("dev.testnet"),"a".repeat(64),U128(100),U64(10),U64(30));}
fn pledge(c:&mut Commitments,who:&str,amount:u128){ctx(who,amount,2,vec![]);c.commit(a("merchant.testnet"),"build".into());}
fn proof()->Vec<u8>{near_sdk::serde_json::to_vec(&near_sdk::serde_json::json!({"id":feature(),"developer":"dev.testnet","terms_hash":"a".repeat(64),"accepted_hash":"a".repeat(64),"approved_sha256":"b".repeat(64),"submitted_sha256":"b".repeat(64),"status":"live"})).unwrap()}
fn verified(c:&mut Commitments){ctx("stranger.testnet",0,3,vec![]);c.verify_delivery(a("merchant.testnet"),"build".into());ctx("escrow.testnet",0,4,vec![PromiseResult::Successful(proof())]);assert!(c.on_delivery(a("merchant.testnet"),"build".into(),U64(1)));}
fn reject(f:impl FnOnce()){assert!(catch_unwind(AssertUnwindSafe(f)).is_err());}
fn conserved(c:&Commitments){assert_eq!(c.contributed,c.held+c.pending+c.released+c.refunded);}
#[test]fn threshold_closes_funding_and_collusion_cannot_release_customer_claim(){let mut c=fresh();campaign(&mut c);pledge(&mut c,"alice.testnet",60);pledge(&mut c,"bob.testnet",40);pledge_rejected(&mut c);verified(&mut c);for actor in ["merchant.testnet","dev.testnet","stranger.testnet"]{ctx(actor,0,5,vec![]);reject(||{c.release(a("merchant.testnet"),"build".into(),"b".repeat(64));});}assert_eq!(c.held,100);conserved(&c);}
fn pledge_rejected(c:&mut Commitments){ctx("alice.testnet",1,3,vec![]);reject(||{c.commit(a("merchant.testnet"),"build".into());});}
#[test]fn customer_acceptance_releases_only_own_share_and_other_customer_can_refund_at_expiry(){let mut c=fresh();campaign(&mut c);pledge(&mut c,"alice.testnet",60);pledge(&mut c,"bob.testnet",40);verified(&mut c);ctx("alice.testnet",0,5,vec![]);c.release(a("merchant.testnet"),"build".into(),"b".repeat(64));ctx("escrow.testnet",0,6,vec![PromiseResult::Successful(vec![])]);assert!(c.on_payment(a("merchant.testnet"),"build".into(),a("alice.testnet"),U64(1)));ctx("bob.testnet",0,30,vec![]);c.refund(a("merchant.testnet"),"build".into());ctx("escrow.testnet",0,31,vec![PromiseResult::Successful(vec![])]);assert!(c.on_payment(a("merchant.testnet"),"build".into(),a("bob.testnet"),U64(1)));assert_eq!((c.released,c.refunded,c.held),(60,40,0));conserved(&c);}
#[test]fn failed_refund_restores_exact_claim_and_stale_or_repeated_callbacks_cannot_pay_twice(){let mut c=fresh();campaign(&mut c);pledge(&mut c,"alice.testnet",60);ctx("alice.testnet",0,10,vec![]);c.refund(a("merchant.testnet"),"build".into());reject(||{c.refund(a("merchant.testnet"),"build".into());});ctx("escrow.testnet",0,11,vec![PromiseResult::Failed]);assert!(!c.on_payment(a("merchant.testnet"),"build".into(),a("alice.testnet"),U64(1)));ctx("alice.testnet",0,12,vec![]);c.refund(a("merchant.testnet"),"build".into());ctx("escrow.testnet",0,13,vec![PromiseResult::Successful(vec![])]);reject(||{c.on_payment(a("merchant.testnet"),"build".into(),a("alice.testnet"),U64(1));});assert!(c.on_payment(a("merchant.testnet"),"build".into(),a("alice.testnet"),U64(2)));reject(||{c.on_payment(a("merchant.testnet"),"build".into(),a("alice.testnet"),U64(2));});conserved(&c);}
#[test]fn cancellation_refunds_funded_campaign_without_admin_seizure(){let mut c=fresh();campaign(&mut c);pledge(&mut c,"alice.testnet",100);ctx("stranger.testnet",0,3,vec![]);reject(||{c.cancel("build".into());});ctx("merchant.testnet",0,3,vec![]);c.cancel("build".into());ctx("alice.testnet",0,4,vec![]);c.refund(a("merchant.testnet"),"build".into());assert_eq!(c.pending,100);conserved(&c);}
#[test]fn wrong_source_wrong_artifact_and_private_callback_do_not_unlock_escrow(){let mut c=fresh();campaign(&mut c);pledge(&mut c,"alice.testnet",100);ctx("alice.testnet",0,3,vec![]);c.verify_delivery(a("merchant.testnet"),"build".into());ctx("stranger.testnet",0,4,vec![PromiseResult::Successful(proof())]);reject(||{c.on_delivery(a("merchant.testnet"),"build".into(),U64(1));});ctx("escrow.testnet",0,4,vec![PromiseResult::Successful(b"null".to_vec())]);assert!(!c.on_delivery(a("merchant.testnet"),"build".into(),U64(1)));ctx("alice.testnet",0,5,vec![]);reject(||{c.release(a("merchant.testnet"),"build".into(),"b".repeat(64));});assert_eq!(c.held,100);}
#[test]fn unfunded_growth_and_early_refund_expired_commit_rejected(){let mut c=fresh();ctx("merchant.testnet",0,1,vec![]);reject(||{c.create_campaign("build".into(),feature(),a("dev.testnet"),"a".repeat(64),U128(100),U64(10),U64(30));});campaign(&mut c);pledge(&mut c,"alice.testnet",60);ctx("alice.testnet",0,9,vec![]);reject(||{c.refund(a("merchant.testnet"),"build".into());});ctx("bob.testnet",40,10,vec![]);reject(||{c.commit(a("merchant.testnet"),"build".into());});let key=(a("merchant.testnet"),"build".to_string());c.campaigns.get_mut(&key).unwrap().storage_available=U128(0);ctx("bob.testnet",40,3,vec![]);reject(||{c.commit(a("merchant.testnet"),"build".into());});conserved(&c);}
#[test]fn oversized_payout_result_keeps_pending_instead_of_unsafe_restoration(){let mut c=fresh();campaign(&mut c);pledge(&mut c,"alice.testnet",60);ctx("alice.testnet",0,10,vec![]);c.refund(a("merchant.testnet"),"build".into());ctx("escrow.testnet",0,11,vec![PromiseResult::Successful(vec![1;10])]);reject(||{c.on_payment(a("merchant.testnet"),"build".into(),a("alice.testnet"),U64(1));});assert_eq!(c.pending,60);conserved(&c);}
